script.text:

function load$GridRequireFieldsDeclarationDetail(g) {g.add_commandEvent(on$GridRequireFieldsDeclarationDetail$ExecuteCommand)}
function dispose$GridRequireFieldsDeclarationDetail(g){try{g.remove_commandEvent(on$GridRequireFieldsDeclarationDetail$ExecuteCommand)}catch(ex){}}
function on$GridRequireFieldsDeclarationDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		case 'AfterCloneRow':
			g.setItemFieldValue('stt_rec0', e.type.Value, '');
			break;
		case 'AfterRemoveRow':
		case 'RowColChange':
			var v = checkRow(g);
			f._setReadOnly(f.getItem('ma_ct'), v);
			break;
		&GridExtraToolbarExecuteCommandScript;
		default:
			break;
	}
}
function checkRow(g) {
	for (var r = 1; r <= g._rowCount; r++) if (!g.blankMemvar(r)) return true;
	return false;
}

			&GridExtraToolbarScript;
